-- Bancos existentes: executar npm run db:migrate (valida dados e permite retomada).
-- Nao inventar CPFs para contas existentes. Corrigir os documentos reais antes da migracao.
ALTER TABLE tb_usuario
  MODIFY cpf CHAR(11) NOT NULL,
  ADD CONSTRAINT ck_usuario_cpf_dv CHECK (cpf REGEXP '^[0-9]{11}$'
    AND cpf NOT IN ('00000000000','11111111111','22222222222','33333333333','44444444444','55555555555','66666666666','77777777777','88888888888','99999999999')
    AND (ASCII(SUBSTRING(cpf,10,1))-48) = MOD(MOD(10*((ASCII(SUBSTRING(cpf,1,1))-48)*10+(ASCII(SUBSTRING(cpf,2,1))-48)*9+(ASCII(SUBSTRING(cpf,3,1))-48)*8+(ASCII(SUBSTRING(cpf,4,1))-48)*7+(ASCII(SUBSTRING(cpf,5,1))-48)*6+(ASCII(SUBSTRING(cpf,6,1))-48)*5+(ASCII(SUBSTRING(cpf,7,1))-48)*4+(ASCII(SUBSTRING(cpf,8,1))-48)*3+(ASCII(SUBSTRING(cpf,9,1))-48)*2),11),10)
    AND (ASCII(SUBSTRING(cpf,11,1))-48) = MOD(MOD(10*((ASCII(SUBSTRING(cpf,1,1))-48)*11+(ASCII(SUBSTRING(cpf,2,1))-48)*10+(ASCII(SUBSTRING(cpf,3,1))-48)*9+(ASCII(SUBSTRING(cpf,4,1))-48)*8+(ASCII(SUBSTRING(cpf,5,1))-48)*7+(ASCII(SUBSTRING(cpf,6,1))-48)*6+(ASCII(SUBSTRING(cpf,7,1))-48)*5+(ASCII(SUBSTRING(cpf,8,1))-48)*4+(ASCII(SUBSTRING(cpf,9,1))-48)*3+(ASCII(SUBSTRING(cpf,10,1))-48)*2),11),10));

ALTER TABLE tb_admin_hotel
  DROP CHECK ck_admin_hotel_cnpj,
  ADD CONSTRAINT ck_admin_hotel_cnpj CHECK (cnpj IS NULL OR REGEXP_LIKE(cnpj, '^[A-Z0-9]{12}[0-9]{2}$', 'c')),
  ADD CONSTRAINT ck_admin_hotel_cnpj_dv CHECK (cnpj IS NULL OR (
    REGEXP_LIKE(cnpj, '^[A-Z0-9]{12}[0-9]{2}$', 'c')
    AND cnpj NOT IN ('00000000000000','11111111111111','22222222222222','33333333333333','44444444444444','55555555555555','66666666666666','77777777777777','88888888888888','99999999999999')
    AND (ASCII(SUBSTRING(cnpj,13,1))-48) = MOD(MOD(10*((ASCII(SUBSTRING(cnpj,1,1))-48)*5+(ASCII(SUBSTRING(cnpj,2,1))-48)*4+(ASCII(SUBSTRING(cnpj,3,1))-48)*3+(ASCII(SUBSTRING(cnpj,4,1))-48)*2+(ASCII(SUBSTRING(cnpj,5,1))-48)*9+(ASCII(SUBSTRING(cnpj,6,1))-48)*8+(ASCII(SUBSTRING(cnpj,7,1))-48)*7+(ASCII(SUBSTRING(cnpj,8,1))-48)*6+(ASCII(SUBSTRING(cnpj,9,1))-48)*5+(ASCII(SUBSTRING(cnpj,10,1))-48)*4+(ASCII(SUBSTRING(cnpj,11,1))-48)*3+(ASCII(SUBSTRING(cnpj,12,1))-48)*2),11),10)
    AND (ASCII(SUBSTRING(cnpj,14,1))-48) = MOD(MOD(10*((ASCII(SUBSTRING(cnpj,1,1))-48)*6+(ASCII(SUBSTRING(cnpj,2,1))-48)*5+(ASCII(SUBSTRING(cnpj,3,1))-48)*4+(ASCII(SUBSTRING(cnpj,4,1))-48)*3+(ASCII(SUBSTRING(cnpj,5,1))-48)*2+(ASCII(SUBSTRING(cnpj,6,1))-48)*9+(ASCII(SUBSTRING(cnpj,7,1))-48)*8+(ASCII(SUBSTRING(cnpj,8,1))-48)*7+(ASCII(SUBSTRING(cnpj,9,1))-48)*6+(ASCII(SUBSTRING(cnpj,10,1))-48)*5+(ASCII(SUBSTRING(cnpj,11,1))-48)*4+(ASCII(SUBSTRING(cnpj,12,1))-48)*3+(ASCII(SUBSTRING(cnpj,13,1))-48)*2),11),10)));

ALTER TABLE tb_log
  ADD COLUMN motivo VARCHAR(500) NOT NULL DEFAULT 'Evento sem motivo informado' AFTER resultado;
